#!/usr/bin/env node
// Downloads dish photos for the full Freezer El Balad catalog from Wikimedia Commons
// (commercial-license only: CC0 / CC BY / CC BY-SA / public domain — no
// NC/ND). Reads scripts/dish-photo-plan.json (generated by
// gen-dish-photo-plan.ts from the seed itself, so filenames always match
// seed.ts imageFor()) and writes each photo to public/images/products/<file>.
//
// Outputs scripts/dish-photo-report.json with source/license/attribution per
// file so the photo strategy can be reviewed before committing.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const PRODUCTS_DIR = path.join(ROOT, 'public', 'images', 'products');
const PLAN = path.join(ROOT, 'scripts', 'dish-photo-plan.json');
const REPORT = path.join(ROOT, 'scripts', 'dish-photo-report.json');

const UA = 'frezzer-el-balad-menu-tool/1.0';
const COMMONS = 'https://commons.wikimedia.org/w/api.php';

// file -> [primary query, fallback query]. Queries for Freezer El Balad meat/chicken products.
const QUERIES = {
  'american-liver-liver.jpg': ['fried liver slices', 'beef liver dish'],
  'baladi-burger-burger-kofta.jpg': ['grilled kofta burger', 'meat burger patty'],
  'baladi-hawawshi-hawawshi.jpg': ['stuffed bread meat', 'hawawshi sandwich'],
  'baladi-kebab-other-products.jpg': ['grilled meat skewer', 'kebab skewer'],
  'beef-liver-liver.jpg': ['beef liver cooked', 'liver slices grilled'],
  'burger-burger-kofta.jpg': ['grilled burger patty', 'beef burger'],
  'chicken-hawawshi-hawawshi.jpg': ['chicken stuffed bread', 'chicken sandwich egyptian'],
  'eastern-sausage-sausage-sosis.jpg': ['sujuk sausage', 'spicy sausage slices'],
  'flank-meat-fresh-meat.jpg': ['raw flank steak', 'beef flank meat'],
  'goulash-other-products.jpg': ['goulash pastry', 'phyllo wrapped meat'],
  'hawawshi-hawawshi.jpg': ['meat stuffed bread', 'egyptian hawawshi'],
  'kofta-burger-kofta.jpg': ['grilled kofta', 'ground meat kebab'],
  'minced-meat-fresh-meat.jpg': ['raw minced meat', 'ground beef'],
  'mozzarella-pane-pane-strips.jpg': ['breaded mozzarella cutlet', 'chicken mozzarella schnitzel'],
  'pane-pane-strips.jpg': ['breaded chicken cutlet', 'chicken schnitzel breaded'],
  'rice-hawawshi-hawawshi.jpg': ['rice stuffed bread', 'hawawshi rice'],
  'shish-frozen-chicken.jpg': ['chicken shish kebab', 'grilled chicken skewers'],
  'sosis-sausage-sosis.jpg': ['sliced sausage', 'breakfast sausage'],
  'steak-meat-fresh-meat.jpg': ['raw beef steak', 'ribeye steak raw'],
  'strips-burger-kofta.jpg': ['chicken strips grilled', 'breaded chicken strips'],
  'wings-frozen-chicken.jpg': ['raw chicken wings', 'frozen chicken wings'],
};

// If a download fails for a house-special item, reuse a visually-similar photo
// downloaded for another dish rather than leaving a placeholder.
const REUSE = {
  'baladi-kebab-other-products.jpg': 'kofta-burger-kofta.jpg',
  'rice-hawawshi-hawawshi.jpg': 'hawawshi-hawawshi.jpg',
  'baladi-hawawshi-hawawshi.jpg': 'hawawshi-hawawshi.jpg',
};

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const fetchWithRetry = async (url, tries = 6) => {
  for (let attempt = 0; attempt < tries; attempt += 1) {
    const res = await fetch(url, { headers: { 'User-Agent': UA }, signal: AbortSignal.timeout(60_000) });
    if (res.status === 429) {
      const wait = Number(res.headers.get('retry-after') ?? '') || 2 + attempt * 4;
      console.warn(`[429] retrying in ${wait}s...`);
      await sleep(wait * 1000);
      continue;
    }
    return res;
  }
  throw new Error('rate-limited after 6 attempts');
};

const api = async (params) => {
  const url = `${COMMONS}?${new URLSearchParams(params)}`;
  const res = await fetchWithRetry(url);
  if (!res.ok) throw new Error(`Commons ${res.status}`);
  return res.json();
};

const search = async (q) => {
  const body = await api({
    action: 'query', list: 'search', srsearch: q, srnamespace: '6',
    srlimit: '15', format: 'json', origin: '*',
  });
  await sleep(600);
  return (body.query?.search ?? []).map((r) => r.title);
};

const infoBatch = async (titles) => {
  const body = await api({
    action: 'query', titles: titles.join('|'), prop: 'imageinfo',
    iiprop: 'url|size|mime|extmetadata', iiurlwidth: '900', format: 'json', origin: '*',
  });
  await sleep(600);
  return Object.values(body.query?.pages ?? {})
    .filter((p) => p.imageinfo?.[0])
    .map((p) => ({ title: p.title, ...p.imageinfo[0] }));
};

const ext = (meta) => meta?.extmetadata ?? {};
const plain = (x) => x?.value ?? '';

// Commercial-safe: CC0 / CC BY / CC BY-SA / public domain, no NC/ND.
const licenseOk = (ii) => {
  const lic = plain(ext(ii).LicenseShortName) || plain(ext(ii).License) || '';
  if (!lic) return false;
  const lower = lic.toLowerCase();
  if (/nc|nd|non[- ]commercial|no[- ]deriv/.test(lower)) return false;
  return /cc|public domain|pdm|cc0/i.test(lower);
};

const words = (q) => q.toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length > 2);

const score = (title, queries) => {
  const t = title.toLowerCase();
  const [q, fb] = queries;
  const qs = words(q).reduce((s, w) => s + (t.includes(w) ? 2 : 0), 0);
  const fs = words(fb ?? '').reduce((s, w) => s + (t.includes(w) ? 1 : 0), 0);
  return qs + fs;
};

const download = async (src) => {
  const res = await fetchWithRetry(src, 8);
  if (!res.ok) throw new Error(`download ${res.status}`);
  const type = res.headers.get('content-type') ?? '';
  if (!type.startsWith('image/')) throw new Error(`not an image: ${type}`);
  return Buffer.from(await res.arrayBuffer());
};

const placeholder = (name) =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600" viewBox="0 0 800 600">
  <rect width="800" height="600" fill="#16161f"/>
  <circle cx="400" cy="250" r="110" fill="#2b2b3d"/>
  <text x="400" y="265" font-family="Segoe UI, Arial" font-size="44" text-anchor="middle" fill="#38BDF8">❄️</text>
  <text x="400" y="420" font-family="Segoe UI, Arial" font-size="30" text-anchor="middle" fill="#e7e7ef">${name}</text>
  <text x="400" y="470" font-family="Segoe UI, Arial" font-size="18" text-anchor="middle" fill="#8a8aa3">picture coming soon - الصورة قريباً</text>
</svg>`;

const plan = JSON.parse(fs.readFileSync(PLAN, 'utf8'));
const onlyArg = process.argv[2] === '--only' ? process.argv[3] : null;
const report = [];

const pickFor = async (row) => {
  const queries = QUERIES[row.file] ?? [row.en, `${row.sub} ${row.en}`];
  const usableFor = (infos) =>
    infos
      .filter((ii) => ii.thumburl && ['image/jpeg', 'image/png', 'image/webp'].includes(ii.mime))
      .filter(licenseOk)
      .map((ii) => ({ ...ii, _score: score(ii.title, queries) }))
      .sort((a, b) => b._score - a._score);
  let titles = [];
  const searchAll = async (qs) => {
    for (const q of qs) {
      try {
        const found = await search(q);
        titles.push(...found.filter((t) => !titles.includes(t)));
      } catch (err) {
        console.error(`[search] ${row.file} "${q}": ${err.message}`);
      }
    }
  };
  await searchAll([queries[0]]);
  let infos = await infoBatch(titles.slice(0, 8));
  let usable = usableFor(infos);
  if (!usable.length && queries[1]) {
    await searchAll([queries[1]]);
    infos = await infoBatch(titles.slice(0, 8));
    usable = usableFor(infos);
  }
  const top = usable[0];
  if (!top) return null;
  const buf = await download(top.thumburl);
  fs.writeFileSync(path.join(PRODUCTS_DIR, row.file), buf);
  report.push({
    file: row.file, status: 'downloaded', title: top.title,
    license: plain(ext(top).LicenseShortName) || plain(ext(top).License),
    artist: plain(ext(top).Artist).replace(/<[^>]+>/g, '').slice(0, 80),
    url: top.url, width: top.width, height: top.height,
  });
  console.log(`  downloaded ${row.file} <- ${top.title} (${top.width}x${top.height}, ${report[report.length - 1].license})`);
};

const CONCURRENCY = 2;
const queue = (onlyArg ? plan.filter((r) => r.file === onlyArg) : [...plan]);
let failed = 0;

const worker = async () => {
  while (queue.length > 0) {
    const row = queue.shift();
    const dest = path.join(PRODUCTS_DIR, row.file);
    if (fs.existsSync(dest)) {
      report.push({ file: row.file, status: 'existing' });
      continue;
    }
    try {
      await pickFor(row);
    } catch (err) {
      failed += 1;
      console.error(`  FAILED ${row.file}: ${err.message}`);
      try {
        const reuse = REUSE[row.file];
        if (reuse) {
          const src = path.join(PRODUCTS_DIR, reuse);
          if (fs.existsSync(src)) {
            fs.copyFileSync(src, dest);
            report.push({ file: row.file, status: 'reused', from: reuse });
            console.log(`  reused ${row.file} <- ${reuse}`);
            continue;
          }
        }
        fs.writeFileSync(dest, placeholder(row.en));
        report.push({ file: row.file, status: 'placeholder' });
        console.log(`  placeholder ${row.file}`);
      } catch {
        report.push({ file: row.file, status: 'error' });
      }
    }
  }
};

await Promise.all(Array.from({ length: CONCURRENCY }, worker));
fs.writeFileSync(REPORT, JSON.stringify(report, null, 2));

const count = (s) => report.filter((r) => r.status === s).length;
console.log(`\n[download-dish-photos] DONE: ${plan.length} files — downloaded ${count('downloaded')}, reused ${count('reused')}, existing ${count('existing')}, placeholder ${count('placeholder')}, error ${count('error')}, failed ${failed}`);
console.log(`[download-dish-photos] report: ${REPORT}`);
